function AbsenceCallDialog({ row, onClose, onSubmit }: { row: AbsenceOperationsRow; onClose: () => void; onSubmit: (values: { status: string; note: string; followUpDate: string }) => Promise<void> }) {
  const [status, setStatus] = useState(row.callStatus),
    [note, setNote] = useState(String(row.call.note || "")),
    [followUpDate, setFollowUpDate] = useState(String(row.call.followUpDate || "")),
    [busy, setBusy] = useState(false),
    [error, setError] = useState("");
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (status === "Follow Up" && !followUpDate) {
      setError("حدد تاريخ المتابعة القادمة");
      return;
    }
    setBusy(true);
    try {
      await onSubmit({
        status,
        note: note.trim(),
        followUpDate: status === "Follow Up" ? followUpDate : "",
      });
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "تعذر حفظ نتيجة المكالمة");
      setBusy(false);
    }
  }
  return (
    <div className="overlay" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
      <form className="dialog compact absence-call-dialog" onSubmit={submit}>
        <div className="dialog-head">
          <div>
            <span className="dialog-icon">☎</span>
            <div>
              <h2>تسجيل مكالمة الغياب</h2>
              <p>
                {row.record.studentName} · {row.date} · بداية {row.time}
              </p>
            </div>
          </div>
          <button type="button" onClick={onClose}>
            ×
          </button>
        </div>
        {error && <p className="form-error">{error}</p>}
        <div className="dynamic-grid dialog-fields">
          <label className="full">
            <span>نتيجة المكالمة *</span>
            <select value={status} onChange={(event) => setStatus(event.target.value)} required>
              <option value="Pending">في انتظار المكالمة</option>
              <option value="Contacted">تم التواصل</option>
              <option value="No Answer">لم يرد</option>
              <option value="Wrong Number">رقم غير صحيح</option>
              <option value="Follow Up">متابعة لاحقًا</option>
            </select>
          </label>
          {status === "Follow Up" && (
            <label className="full">
              <span>تاريخ المتابعة *</span>
              <input type="date" min={egyptDateKey()} value={followUpDate} onChange={(event) => setFollowUpDate(event.target.value)} required />
            </label>
          )}
          <label className="full">
            <span>ملاحظات المكالمة</span>
            <textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="اكتب نتيجة التواصل وأي ملاحظات مهمة..." />
          </label>
        </div>
        <div className="dialog-foot">
          <button type="button" className="secondary" onClick={onClose}>
            إلغاء
          </button>
          <button className="primary" disabled={busy}>
            {busy ? "جارٍ الحفظ..." : "حفظ النتيجة"}
          </button>
        </div>
      </form>
    </div>
  );
}
function zeroLevelPaymentTypeLabel(title: string) {
  const value = title
    .toLowerCase()
    .replace(/[\s_-]+/g, " ")
    .trim();
  if (/material book|\bbooks?\b/.test(value)) return "Books";
  if (/make up|makeup/.test(value)) return "Make Up";
  if (/delivery|shipping|courier/.test(value)) return "Delivery";
  if (/certificate/.test(value)) return "Certificate";
  if (/placement/.test(value)) return "Placement Test";
  if (/\bexam\b|\btest\b/.test(value)) return "Test";
  return "Other";
}
function paymentTypeLabel(record: StudentRecord, data: Setup): string {
  const details = studentRecordDetails(record),
    stored = String(details.paymentType || "").trim();
  if (details.isDebtPayment || String(details.offer || details.originalOffer || "").toLowerCase().includes("rest of money")) {
    const main = data.studentRecords.find((item) => item.studentId === record.studentId && item.kind === "payment" && studentRecordDetails(item).isMainPayment && studentRecordDetails(item).main === details.main);
    return main && main.id !== record.id ? paymentTypeLabel(main, data) : stored || "New Comers";
  }
  if (stored) return stored;
  const levels = Math.max(0, Number(details.levels || 0));
  if (levels === 0) return zeroLevelPaymentTypeLabel(String(details.offer || details.offerName || ""));
  const prior = data.studentRecords
    .filter((item) => item.studentId === record.studentId && item.kind === "payment" && (item.recordDate < record.recordDate || (item.recordDate === record.recordDate && item.id < record.id)))
    .map((item) => ({ record: item, details: studentRecordDetails(item) }))
    .filter((item) => item.details.isMainPayment && !item.details.voided && Number(item.details.levels || 0) > 0)
    .sort((a, b) => a.record.recordDate.localeCompare(b.record.recordDate) || a.record.id - b.record.id);
  if (!prior.length) return "New Comers";
  if (egyptDateKey(systemDate(prior[0].record.recordDate)) === egyptDateKey(systemDate(record.recordDate))) return "New Comers";
  const purchased = prior.reduce((sum, item) => sum + Math.max(0, Number(item.details.levels || 0) - Number(item.details.refundedLevels || 0) - Number(item.details.transferredLevels || 0)), 0),
    memberships = data.groupMembers.filter((item) => item.studentId === record.studentId && systemDate(item.joinedAt) <= systemDate(record.recordDate)).length,
    student = data.students.find((item) => item.id === record.studentId),
    adjustment = student ? Number(studentDetails(student).misplacedLevelAdjustment || 0) : 0;
  return Math.max(0, purchased - memberships - adjustment) <= 1 ? "Retention" : "Renewal";
}
function StudentPhoneLink({ studentId, phone, fallback = "—" }: { studentId: number | string; phone?: string | null; fallback?: string }) {
  if (!phone) return <>{fallback}</>;
  return (
    <button
      type="button"
      className="student-phone-link ltr-cell"
      title="فتح بروفايل الطالب"
      onClick={(event) => {
        event.stopPropagation();
        window.dispatchEvent(new CustomEvent("open-student-profile", { detail: { studentId } }));
      }}
    >
      {displayCustomerPhone(phone, fallback)}
    </button>
  );
}
function groupWeekdays(startDate: string, roundTitle = "") {
  return scheduledGroupWeekdays(startDate, roundTitle);
}
function automaticSessionNumber(startDate: string, targetDate: string, roundTitle = "") {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate.slice(0, 10)) || !/^\d{4}-\d{2}-\d{2}$/.test(targetDate.slice(0, 10))) return 0;
  const start = new Date(`${startDate.slice(0, 10)}T12:00:00Z`),
    target = new Date(`${targetDate.slice(0, 10)}T12:00:00Z`);
  if (target < start) return 0;
  const days = new Set(groupWeekdays(startDate, roundTitle));
  let count = 0;
  for (const date = new Date(start); date <= target; date.setUTCDate(date.getUTCDate() + 1)) if (days.has(date.getUTCDay())) count++;
  return days.has(target.getUTCDay()) ? count : 0;
}
function currentGroupSessionNumber(startDate: string, targetDate = egyptDateKey(), roundTitle = "") {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate.slice(0, 10)) || !/^\d{4}-\d{2}-\d{2}$/.test(targetDate.slice(0, 10))) return 0;
  const start = new Date(`${startDate.slice(0, 10)}T12:00:00Z`),
    target = new Date(`${targetDate.slice(0, 10)}T12:00:00Z`);
  if (target < start) return 0;
  const days = new Set(groupWeekdays(startDate, roundTitle));
  let count = 0;
  for (const date = new Date(start); date <= target; date.setUTCDate(date.getUTCDate() + 1)) if (days.has(date.getUTCDay())) count++;
  return count;
}

function RetentionStatusPage({ data, mutate, setNotice }: { data: Setup; mutate: (payload: Record<string, unknown>) => Promise<void>; setNotice: (message: string) => void }) {
  const [query, setQuery] = useState(""),
    [statusFilter, setStatusFilter] = useState(""),
    [trackId, setTrackId] = useState(""),
    [branchId, setBranchId] = useState(""),
    [editing, setEditing] = useState<Student | null>(null),
    recordDetails = (record: StudentRecord) => studentRecordDetails(record),
    today = egyptDateKey();
  const rows = data.students
      .map((student) => {
        const payments = data.studentRecords.filter((record) => record.studentId === student.id && record.kind === "payment"),
          purchased = payments.reduce((sum, record) => {
            const item = recordDetails(record);
            return sum + (item.isMainPayment && !item.voided ? Math.max(0, Number(item.levels || 0) - Number(item.refundedLevels || 0) - Number(item.transferredLevels || 0)) : 0);
          }, 0),
          memberships = data.groupMembers.filter((member) => member.studentId === student.id).length,
          adjustment = Number(studentDetails(student).misplacedLevelAdjustment || 0),
          remaining = Math.max(0, purchased - memberships - adjustment),
          workflow = (studentDetails(student).retentionWorkflow || {}) as Record<string, unknown>,
          workflowStatus = String(workflow.status || "Not Contacted");
        return {
          student,
          purchased,
          memberships,
          remaining,
          workflow,
          workflowStatus,
        };
      })
      .filter((row) => {
        const haystack = [row.student.fullName, row.student.mobile, row.student.trackName, row.student.branchName, row.workflow.notes, row.workflow.updatedBy].join(" ").toLowerCase();
        return ((row.purchased > 0 && row.remaining === 0) || Boolean(row.workflow.status)) && haystack.includes(query.toLowerCase()) && (!statusFilter || row.workflowStatus === statusFilter) && (!trackId || String(row.student.trackId || "") === trackId) && (!branchId || String(row.student.branchId || "") === branchId);
      })
      .sort((a, b) => String(a.workflow.nextFollowupDate || "9999").localeCompare(String(b.workflow.nextFollowupDate || "9999")) || a.student.fullName.localeCompare(b.student.fullName)),
    followUpRows = rows.filter((row) => row.workflowStatus === "Follow Up"),
    overdue = followUpRows.filter((row) => String(row.workflow.nextFollowupDate || "") < today).length;
  const exportRows = () =>
    downloadFinancialCsv(
      "retention-status.csv",
      ["Student", "Mobile", "Track", "Branch", "Purchased", "Studied", "Remaining", "Status", "Next Follow Up", "Notes", "Updated By", "Updated At"],
      rows.map((row) => [row.student.fullName, row.student.mobile, row.student.trackName || "", row.student.branchName || "", row.purchased, row.memberships, row.remaining, row.workflowStatus, String(row.workflow.nextFollowupDate || ""), String(row.workflow.notes || ""), String(row.workflow.updatedBy || ""), String(row.workflow.updatedAt || "")]),
    );
  return (
    <div className="content-stack retention-status-page">
      <section className="metrics">
        <Metric label="Not Contacted" value={rows.filter((row) => row.workflowStatus === "Not Contacted").length} hint="تحتاج أول تواصل" tone="orange" />
        <Metric label="Follow Up" value={followUpRows.length} hint={`${overdue} متابعة متأخرة`} tone="purple" />
        <Metric label="Renewed" value={rows.filter((row) => row.workflowStatus === "Renewed").length} hint="تمت إضافة مستويات" tone="green" />
        <Metric label="Not Interested" value={rows.filter((row) => row.workflowStatus === "Not Interested").length} hint="لا يرغب في التجديد" tone="blue" />
      </section>
      <section className="panel">
        <div className="panel-head">
          <div>
            <span className="mini-label">RETENTION WORKFLOW</span>
            <h2>Retention Status</h2>
            <p>تسجيل نتيجة التواصل وموعد المتابعة والموظف الذي حدّث حالة الطالب.</p>
          </div>
          <button className="secondary" onClick={exportRows}>
            ⇩ Export
          </button>
        </div>
        <div className="retention-filters">
          <label className="search">
            <span>⌕</span>
            <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="ابحث بالطالب أو الموبايل..." />
          </label>
          <select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}>
            <option value="">All Statuses</option>
            <option>Not Contacted</option>
            <option>Follow Up</option>
            <option>Renewed</option>
            <option>Not Interested</option>
          </select>
          <select value={trackId} onChange={(event) => setTrackId(event.target.value)}>
            <option value="">All Tracks</option>
            {data.tracks.map((track) => (
              <option key={track.id} value={track.id}>
                {track.title}
              </option>
            ))}
          </select>
          <select value={branchId} onChange={(event) => setBranchId(event.target.value)}>
            <option value="">All Branches</option>
            {data.branches.map((branch) => (
              <option key={branch.id} value={branch.id}>
                {branch.name}
              </option>
            ))}
          </select>
          <button
            className="secondary"
            onClick={() => {
              setQuery("");
              setStatusFilter("");
              setTrackId("");
              setBranchId("");
            }}
          >
            Reset
          </button>
        </div>
        {rows.length ? (
          <div className="table-wrap retention-status-table">
            <table>
              <thead>
                <tr>
                  <th>#</th>
                  <th>Student</th>
                  <th>Mobile</th>
                  <th>Track</th>
                  <th>Branch</th>
                  <th>Remaining</th>
                  <th>Status</th>
                  <th>Next Follow Up</th>
                  <th>Notes</th>
                  <th>Updated By</th>
                  <th>Last Update</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((row, index) => (
                  <tr key={row.student.id} className={row.workflowStatus === "Follow Up" && String(row.workflow.nextFollowupDate || "") < today ? "retention-overdue" : ""}>
                    <td>{index + 1}</td>
                    <td>
                      <strong>{row.student.fullName}</strong>
                    </td>
                    <td>
                      <StudentPhoneLink studentId={row.student.id} phone={row.student.mobile} />
                    </td>
                    <td>{row.student.trackName || "—"}</td>
                    <td>{row.student.branchName || "—"}</td>
                    <td>{row.remaining}</td>
                    <td>
                      <span className={`retention-workflow-status ${row.workflowStatus.toLowerCase().replace(/\s+/g, "-")}`}>{row.workflowStatus}</span>
                    </td>
                    <td>{row.workflow.nextFollowupDate ? formatDate(String(row.workflow.nextFollowupDate)) : "—"}</td>
                    <td className="notes-cell">{String(row.workflow.notes || "—")}</td>
                    <td>{String(row.workflow.updatedBy || "—")}</td>
                    <td>{row.workflow.updatedAt ? formatDate(String(row.workflow.updatedAt)) : "—"}</td>
                    <td>
                      <button className="primary edit" onClick={() => setEditing(row.student)}>
                        Update Status
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="empty">
            <span>◷</span>
            <h3>لا توجد حالات Retention</h3>
            <p>الطلاب يظهرون تلقائيًا بعد استهلاك كل المستويات المحجوزة.</p>
          </div>
        )}
      </section>
      {editing && (
        <RetentionStatusDialog
          student={editing}
          onClose={() => setEditing(null)}
          onSubmit={async (values) => {
            await mutate({
              action: "updateRetentionStatus",
              studentId: editing.id,
              ...values,
            });
            setEditing(null);
            setNotice("تم تحديث حالة Retention وحفظ المتابعة");
          }}
        />
      )}
    </div>
  );
}

function RetentionStatusDialog({ student, onClose, onSubmit }: { student: Student; onClose: () => void; onSubmit: (values: { status: string; notes: string; nextFollowupDate: string }) => Promise<void> }) {
  const workflow = (studentDetails(student).retentionWorkflow || {}) as Record<string, unknown>,
    [status, setStatus] = useState(String(workflow.status || "Not Contacted")),
    [notes, setNotes] = useState(String(workflow.notes || "")),
    [nextFollowupDate, setNextFollowupDate] = useState(String(workflow.nextFollowupDate || "")),
    [busy, setBusy] = useState(false),
    [error, setError] = useState("");
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (status === "Follow Up" && !nextFollowupDate) {
      setError("حدد تاريخ المتابعة القادمة");
      return;
    }
    setBusy(true);
    try {
      await onSubmit({
        status,
        notes: notes.trim(),
        nextFollowupDate: status === "Follow Up" ? nextFollowupDate : "",
      });
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "تعذر تحديث الحالة");
      setBusy(false);
    }
  }
  return (
    <div className="overlay" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
      <form className="dialog compact retention-status-dialog" onSubmit={submit}>
        <div className="dialog-head">
          <div>
            <span className="dialog-icon">↻</span>
            <div>
              <h2>Update Retention Status</h2>
              <p>
                {student.fullName} · <StudentPhoneLink studentId={student.id} phone={student.mobile} />
              </p>
            </div>
          </div>
          <button type="button" onClick={onClose}>
            ×
          </button>
        </div>
        {error && <p className="form-error">{error}</p>}
        <div className="dynamic-grid dialog-fields">
          <label className="full">
            <span>Status *</span>
            <select value={status} onChange={(event) => setStatus(event.target.value)}>
              <option>Not Contacted</option>
              <option>Follow Up</option>
              <option>Renewed</option>
              <option>Not Interested</option>
            </select>
          </label>
          {status === "Follow Up" && (
            <label className="full">
              <span>Next Follow Up Date *</span>
              <input required type="date" min={egyptDateKey()} value={nextFollowupDate} onChange={(event) => setNextFollowupDate(event.target.value)} />
            </label>
          )}
          <label className="full">
            <span>Notes</span>
            <textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="اكتب نتيجة التواصل وملاحظات المتابعة..." />
          </label>
        </div>
        <div className="dialog-foot">
          <button type="button" className="secondary" onClick={onClose}>
            إلغاء
          </button>
          <button className="primary" disabled={busy}>
            {busy ? "جارٍ الحفظ..." : "حفظ الحالة"}
          </button>
        </div>
      </form>
    </div>
  );
}

function retentionTargetDetails(item: SettingsEntity) {
  try {
    return JSON.parse(item.customData || "{}") as {
      targetType?: string;
      targetId?: number;
      month?: string;
      amount?: number;
    };
  } catch {
    return {};
  }
}
function retentionMoneyRows(data: Setup, from: string, to: string) {
  const groups = data.settingsEntities.filter((item) => item.kind === "group"),
    groupById = new Map(groups.map((item) => [item.id, item])),
    batchById = new Map(data.settingsEntities.filter((item) => item.kind === "education_batch").map((item) => [item.id, item])),
    employeeById = new Map(data.employees.map((item) => [item.id, item])),
    employeeByName = new Map(data.employees.map((item) => [item.fullName.trim().toLowerCase().replace(/\s+/g, " "), item])),
    branchById = new Map(data.branches.map((item) => [item.id, item]));
  const groupInfo = (group: SettingsEntity | undefined) => {
    try {
      return JSON.parse(group?.customData || "{}") as Record<string, unknown>;
    } catch {
      return {};
    }
  };
  return data.studentRecords
    .filter((record) => record.kind === "payment" && record.recordDate.slice(0, 10) >= from && record.recordDate.slice(0, 10) <= to)
    .map((record) => {
      const details = studentRecordDetails(record),
        type = paymentTypeLabel(record, data),
        normalized = type.toLowerCase(),
        isRenewal = normalized === "retention" || normalized === "renewal",
        paid = Number(details.netPaid ?? Number(details.paid || 0) - Number(details.refunded || 0));
      if (!isRenewal || details.voided || paid <= 0) return null;
      const student = data.students.find((item) => item.id === record.studentId),
        paymentDate = record.recordDate.slice(0, 10),
        memberships = data.groupMembers
          .filter((item) => item.studentId === record.studentId)
          .map((member) => {
            const group = groupById.get(member.groupId),
              info = groupInfo(group),
              startDate = String(info.startDate || member.joinedAt || "").slice(0, 10),
              endDate = String(info.endDate || "").slice(0, 10),
              status = String(info.groupStatus || "").trim().toLowerCase(),
              runningAtPayment = (!startDate || startDate <= paymentDate) && (!endDate || endDate >= paymentDate) && status !== "done" && status !== "cancelled";
            return { member, group, info, startDate, runningAtPayment };
          })
          .sort((a, b) => b.startDate.localeCompare(a.startDate) || b.member.id - a.member.id),
        team = memberships.find((item) => item.runningAtPayment) || memberships.find((item) => !item.startDate || item.startDate <= paymentDate) || memberships[0],
        batch = batchById.get(Number(team?.info.batchId)),
        branch = branchById.get(Number(team?.info.branchId || student?.branchId)),
        sourceAdminName = String(team?.info.sourceAdminName || "").trim(),
        sourceTeacherName = String(team?.info.sourceTeacherName || "").trim(),
        admin = employeeById.get(Number(team?.info.adminId)) || employeeByName.get(sourceAdminName.toLowerCase().replace(/\s+/g, " ")),
        teacher = employeeById.get(Number(team?.info.teacherId)) || employeeByName.get(sourceTeacherName.toLowerCase().replace(/\s+/g, " "));
      return {
        record,
        details,
        type,
        amount: paid,
        date: paymentDate,
        student,
        batch,
        branch,
        admin,
        teacher,
        adminName: admin?.fullName || sourceAdminName || "-",
        teacherName: teacher?.fullName || sourceTeacherName || "-",
      };
    })
    .filter((item): item is NonNullable<typeof item> => Boolean(item));
}

function RetentionMoneyPage({ data, reload }: { data: Setup; reload: (query: Record<string, string>) => Promise<void> }) {
  const today = egyptDateKey(),
    monthStart = `${today.slice(0, 7)}-01`,
    [from, setFrom] = useState(monthStart),
    [to, setTo] = useState(today),
    [branchId, setBranchId] = useState(""),
    [loading, setLoading] = useState(false),
    month = from.slice(0, 7),
    allRows = retentionMoneyRows(data, from, to),
    rows = allRows.filter((row) => !branchId || String(row.branch?.id || "") === branchId),
    targets = data.settingsEntities
      .filter((item) => item.kind === "retention_target" && item.isActive)
      .map((item) => ({ item, ...retentionTargetDetails(item) }))
      .filter((item) => item.month === month),
    money = (value: number) => `${Math.round(value).toLocaleString("en-US")} EGP`;
  const dates: string[] = [];
  for (let cursor = new Date(`${from}T12:00:00Z`), end = new Date(`${to}T12:00:00Z`); cursor <= end; cursor.setUTCDate(cursor.getUTCDate() + 1)) dates.push(cursor.toISOString().slice(0, 10));
  const daily = dates.map((date) => {
      const items = rows.filter((row) => row.date === date);
      return {
        date,
        count: items.length,
        amount: items.reduce((sum, item) => sum + item.amount, 0),
      };
    }),
    total = rows.reduce((sum, row) => sum + row.amount, 0),
    branchTarget = targets.filter((item) => item.targetType === "branch" && (!branchId || String(item.targetId) === branchId)).reduce((sum, item) => sum + Number(item.amount || 0), 0),
    achievement = branchTarget ? Math.round((total * 100) / branchTarget) : 0;
  const targetFor = (type: string, id: number) => Number(targets.find((item) => item.targetType === type && Number(item.targetId) === id)?.amount || 0),
    breakdown = <T,>(items: T[], id: (item: T) => number, name: (item: T) => string, amount: (item: T) => number, type?: string) =>
      Array.from(
        items
          .reduce((map, item) => {
            const key = id(item);
            if (!key) return map;
            const current = map.get(key) || {
              id: key,
              name: name(item),
              count: 0,
              amount: 0,
            };
            current.count++;
            current.amount += amount(item);
            map.set(key, current);
            return map;
          }, new Map<number, { id: number; name: string; count: number; amount: number }>())
          .values(),
      )
        .map((item) => {
          const target = type ? targetFor(type, item.id) : 0;
          return {
            ...item,
            target,
            rate: target ? Math.round((item.amount * 100) / target) : 0,
          };
        })
        .sort((a, b) => b.amount - a.amount),
    branchRows = data.branches
      .filter((item) => item.isActive && (!branchId || String(item.id) === branchId))
      .map((branch) => {
        const achieved = rows.filter((row) => row.branch?.id === branch.id);
        const amount = achieved.reduce((sum, row) => sum + row.amount, 0),
          target = targetFor("branch", branch.id);
        return {
          id: branch.id,
          name: branch.name,
          count: achieved.length,
          amount,
          target,
          rate: target ? Math.round((amount * 100) / target) : 0,
        };
      })
      .sort((a, b) => b.amount - a.amount),
    adminRows = breakdown(
      rows.filter((row) => row.admin),
      (row) => row.admin!.id,
      (row) => row.admin!.fullName,
      (row) => row.amount,
      "admin",
    ),
    teacherRows = breakdown(
      rows.filter((row) => row.teacher),
      (row) => row.teacher!.id,
      (row) => row.teacher!.fullName,
      (row) => row.amount,
    );
  const types = Array.from(rows.reduce((map, row) => map.set(row.type, (map.get(row.type) || 0) + row.amount), new Map<string, number>()))
    .map(([label, value]) => ({
      label,
      value,
      count: rows.filter((row) => row.type === label).length,
    }))
    .sort((a, b) => b.value - a.value);
  async function apply() {
    setLoading(true);
    try {
      await reload({ from, to });
    } finally {
      setLoading(false);
    }
  }
  async function exportRawData() {
    const XLSX = await import("xlsx"),
      exportRows = [...rows]
        .sort((a, b) => b.date.localeCompare(a.date) || b.record.id - a.record.id)
        .map((row) => ({
          "تاريخ الدفع": row.date,
          "اسم الطالب": row.student?.fullName || row.record.studentName,
          "رقم الطالب": row.student?.mobile || "-",
          "النوع": row.type,
          "باتش التجديد": row.batch?.title || "-",
          "الأدمن": row.adminName,
          "المدرس": row.teacherName,
          "المبلغ المدفوع": row.amount,
          "لوكيشن الطالب": row.branch?.name || row.student?.branchName || "-",
        })),
      sheet = XLSX.utils.json_to_sheet(exportRows),
      book = XLSX.utils.book_new();
    sheet["!cols"] = [{ wch: 14 }, { wch: 30 }, { wch: 18 }, { wch: 14 }, { wch: 18 }, { wch: 24 }, { wch: 24 }, { wch: 16 }, { wch: 18 }];
    XLSX.utils.book_append_sheet(book, sheet, "Retention Money");
    XLSX.writeFile(book, `retention-money-${from}-${to}.xlsx`);
  }
  return (
    <div className="content-stack retention-money-page">
      <section className="retention-money-hero">
        <div>
          <span>OPERATIONS · MONEY RETENTION</span>
          <h2>Retention Money</h2>
          <p>القيمة الصافية لإيصالات Retention وRenewal وربطها بفريق الجروب وقت الدفع.</p>
        </div>
        <div className="retention-money-filter">
          <label>
            من
            <input type="date" value={from} onChange={(event) => setFrom(event.target.value)} />
          </label>
          <label>
            إلى
            <input type="date" min={from} value={to} onChange={(event) => setTo(event.target.value)} />
          </label>
          <select value={branchId} onChange={(event) => setBranchId(event.target.value)}>
            <option value="">كل الفروع</option>
            {data.branches
              .filter((item) => item.isActive)
              .map((branch) => (
                <option key={branch.id} value={branch.id}>
                  {branch.name}
                </option>
              ))}
          </select>
          <button onClick={apply} disabled={loading}>
            {loading ? "جارٍ التحميل..." : "تطبيق"}
          </button>
        </div>
      </section>
      <section className="retention-money-kpis">
        <article>
          <span>↻</span>
          <div>
            <small>إجمالي التجديدات</small>
            <strong>{money(total)}</strong>
            <em>{rows.length.toLocaleString()} إيصال</em>
          </div>
        </article>
        <article>
          <span>◎</span>
          <div>
            <small>متوسط الإيصال</small>
            <strong>{money(rows.length ? total / rows.length : 0)}</strong>
            <em>متوسط صافي التحصيل</em>
          </div>
        </article>
        <article>
          <span>◫</span>
          <div>
            <small>تارجت الفروع</small>
            <strong>{money(branchTarget)}</strong>
            <em>للشهر {month}</em>
          </div>
        </article>
        <article className="featured">
          <span>↗</span>
          <div>
            <small>تحقيق التارجت</small>
            <strong>{achievement}%</strong>
            <em>{money(Math.max(0, branchTarget - total))} متبقي</em>
          </div>
        </article>
      </section>
      <section className="retention-money-chart-grid">
        <article className="panel retention-daily-card report-download-surface">
          <div className="panel-head">
            <div>
              <span className="mini-label">DAILY MOMENTUM</span>
              <h2>التجديد اليومي</h2>
              <p>المبلغ المالي وعدد إيصالات التجديد لكل يوم.</p>
            </div>
            <ReportImageDownload filename={`daily-momentum-${from}-${to}`} />
          </div>
          <RetentionDailyChart rows={daily} />
        </article>
        <article className="panel retention-pie-card report-download-surface">
          <div className="panel-head">
            <div>
              <span className="mini-label">RENEWAL MIX</span>
              <h2>نوع التجديد</h2>
              <p>توزيع قيمة التحصيل حسب نوع التجديد.</p>
            </div>
            <ReportImageDownload filename={`renewal-mix-${from}-${to}`} />
          </div>
          <RetentionMoneyPie rows={types} total={total} />
        </article>
      </section>
      <section className="retention-employee-chart-grid">
        <RetentionEmployeeBar title="ترتيب الأدمنز" roleLabel="أدمن" rows={adminRows} money={money} filename={`admins-ranking-${from}-${to}`} />
        <RetentionEmployeeBar title="ترتيب المدرسين" roleLabel="مدرس" rows={teacherRows} money={money} filename={`teachers-ranking-${from}-${to}`} variant="teacher" />
      </section>
      <section className="retention-branch-table-row">
        <RetentionMoneyTable title="أداء الفروع" label="الفرع" rows={branchRows} money={money} filename={`branches-performance-${from}-${to}`} showTarget />
      </section>
      <section className="retention-team-table-grid">
        <RetentionMoneyTable title="أداء الأدمنز" label="الأدمن" rows={adminRows} money={money} filename={`admins-performance-${from}-${to}`} showTarget />
        <RetentionMoneyTable title="أداء المدرسين" label="المدرس" rows={teacherRows} money={money} filename={`teachers-performance-${from}-${to}`} />
      </section>
      <article className="panel retention-money-raw-data">
        <div className="panel-head">
          <div>
            <span className="mini-label">RAW DATA</span>
            <h2>تفاصيل الطلاب المجددين</h2>
            <p>كل إيصالات Retention وRenewal المطابقة للفترة والفرع المحددين.</p>
          </div>
          <div className="retention-raw-actions">
            <strong>{rows.length.toLocaleString()} إيصال</strong>
            <button className="secondary" onClick={() => void exportRawData()} disabled={!rows.length}>تصدير Excel</button>
          </div>
        </div>
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>تاريخ الدفع</th>
                <th>اسم الطالب</th>
                <th>رقم الطالب</th>
                <th>النوع</th>
                <th>باتش التجديد</th>
                <th>الأدمن</th>
                <th>المدرس</th>
                <th>المبلغ المدفوع</th>
                <th>لوكيشن الطالب</th>
              </tr>
            </thead>
            <tbody>
              {rows.length ? (
                [...rows]
                  .sort((a, b) => b.date.localeCompare(a.date) || b.record.id - a.record.id)
                  .map((row) => (
                    <tr key={row.record.id}>
                      <td className="ltr-cell">{row.date}</td>
                      <td><strong>{row.student?.fullName || row.record.studentName}</strong></td>
                      <td className="ltr-cell">{row.student?.mobile || "-"}</td>
                      <td><span className={`retention-raw-type ${row.type.toLowerCase()}`}>{row.type}</span></td>
                      <td>{row.batch?.title || "-"}</td>
                      <td>{row.adminName}</td>
                      <td>{row.teacherName}</td>
                      <td><strong>{money(row.amount)}</strong></td>
                      <td>{row.branch?.name || row.student?.branchName || "-"}</td>
                    </tr>
                  ))
              ) : (
                <tr><td colSpan={9}>لا توجد دفعات Retention أو Renewal في الفترة المحددة.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </article>
    </div>
  );
}

function RetentionDailyChart({ rows }: { rows: Array<{ date: string; count: number; amount: number }> }) {
  const width = 900,
    height = 250,
    pad = 38,
    maxAmount = Math.max(1, ...rows.map((row) => row.amount)),
    maxCount = Math.max(1, ...rows.map((row) => row.count)),
    x = (index: number) => pad + (rows.length <= 1 ? 0 : (index * (width - pad * 2)) / (rows.length - 1)),
    yAmount = (value: number) => height - pad - (value * (height - pad * 2)) / maxAmount,
    yCount = (value: number) => height - pad - (value * (height - pad * 2)) / maxCount,
    amountPoints = rows.map((row, index) => ({
      x: x(index),
      y: yAmount(row.amount),
    })),
    countPoints = rows.map((row, index) => ({
      x: x(index),
      y: yCount(row.count),
    })),
    smooth = (points: Array<{ x: number; y: number }>) =>
      points.length
        ? points.slice(1).reduce((path, point, index) => {
            const previous = points[index],
              middle = (previous.x + point.x) / 2;
            return `${path} C ${middle} ${previous.y}, ${middle} ${point.y}, ${point.x} ${point.y}`;
          }, `M ${points[0].x} ${points[0].y}`)
        : "",
    amountPath = smooth(amountPoints),
    countPath = smooth(countPoints),
    areaPath = amountPoints.length ? `${amountPath} L ${amountPoints.at(-1)?.x} ${height - pad} L ${amountPoints[0].x} ${height - pad} Z` : "",
    step = Math.max(1, Math.ceil(rows.length / 6)),
    compact = (value: number) =>
      new Intl.NumberFormat("en-US", {
        notation: "compact",
        maximumFractionDigits: 1,
      }).format(Math.round(value));
  return (
    <div className="retention-daily-chart">
      <div className="retention-chart-legend">
        <span>
          <i className="amount" />
          المبلغ
        </span>
        <span>
          <i className="count" />
          عدد الإيصالات
        </span>
      </div>
      <svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="شارت التجديد اليومي">
        <defs>
          <linearGradient id="retentionArea" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#24715e" stopOpacity=".34" />
            <stop offset="1" stopColor="#24715e" stopOpacity=".02" />
          </linearGradient>
        </defs>
        {[0, 1, 2, 3, 4].map((line) => (
          <line key={line} x1={pad} x2={width - pad} y1={pad + (line * (height - pad * 2)) / 4} y2={pad + (line * (height - pad * 2)) / 4} className="grid-line" />
        ))}
        {rows.length > 0 && (
          <>
            <path d={areaPath} fill="url(#retentionArea)" />
            <path d={amountPath} className="amount-line" />
            <path d={countPath} className="count-line" />
            {rows.map((row, index) => (
              <Fragment key={row.date}>
                <circle cx={amountPoints[index].x} cy={amountPoints[index].y} r="3.5" className="amount-point">
                  <title>
                    {row.date}: {Math.round(row.amount).toLocaleString()} EGP
                  </title>
                </circle>
                {row.amount > 0 && (
                  <text className="data-label" x={amountPoints[index].x} y={Math.max(pad - 7, amountPoints[index].y - 10)} textAnchor="middle">
                    {compact(row.amount)}
                  </text>
                )}
                {index % step === 0 || index === rows.length - 1 ? (
                  <text x={x(index)} y={height - 8} textAnchor="middle">
                    {row.date.slice(5)}
                  </text>
                ) : null}
              </Fragment>
            ))}
          </>
        )}
      </svg>
    </div>
  );
}

function RetentionMoneyPie({ rows, total }: { rows: Array<{ label: string; value: number; count: number }>; total: number }) {
  const colors = ["#24715e", "#d9a744", "#5577b9", "#9b6db2"],
    segments = rows.reduce(
      (result, row, index) => {
        const start = result.total,
          end = start + (total ? (row.value * 100) / total : 0);
        result.parts.push(`${colors[index % colors.length]} ${start}% ${end}%`);
        result.total = end;
        return result;
      },
      { parts: [] as string[], total: 0 },
    );
  return (
    <div className="retention-money-pie-wrap">
      <div
        className="retention-money-pie"
        style={{
          background: rows.length ? `conic-gradient(${segments.parts.join(",")})` : "#edf1ef",
        }}
      >
        <span>
          <b>{Math.round(total).toLocaleString()}</b>
          <small>EGP</small>
        </span>
      </div>
      <div className="retention-money-pie-legend">
        {rows.map((row, index) => (
          <div key={row.label}>
            <i style={{ background: colors[index % colors.length] }} />
            <span>
              <strong>{row.label}</strong>
              <small>{Math.round(row.value).toLocaleString()} EGP</small>
            </span>
            <b>{total ? Math.round((row.value * 100) / total) : 0}%</b>
          </div>
        ))}
      </div>
    </div>
  );
}

