function CallDialog({ data, onClose, onSubmit }: { data: Setup; onClose: () => void; onSubmit: (p: Record<string, unknown>) => Promise<void> }) {
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  const [values, setValues] = useState<Record<string, unknown>>({
    direction: "واردة",
    result: callResultOptions(data)[0] || "",
    callAt: now.toISOString().slice(0, 16),
    country: "مصر",
    governorate: "القاهرة",
  });
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const makeField = (id: number, fieldKey: string, label: string, type: string, placeholder: string, required = 0, width: "full" | "half" = "half", optionsJson = "[]"): Field => ({
    id,
    fieldKey,
    label,
    type,
    placeholder,
    required,
    visible: 1,
    sortOrder: -id,
    width,
    version: 1,
    optionsJson,
  });
  const fields = [makeField(-1, "fullName", "الاسم", "text", "اكتب اسم العميل", 1, "full"), makeField(-2, "phone", "رقم الموبايل 1", "tel", "01xxxxxxxxx", 1), makeField(-3, "secondaryPhone", "رقم الموبايل 2", "tel", "رقم إضافي"), makeField(-4, "track", "التراك", "select", "اختر التراك", 1), makeField(-5, "branchId", "الفرع", "select", "اختر الفرع", 1), makeField(-6, "source", "السورس", "select", "اختر السورس", 1), makeField(-7, "country", "البلد", "select", "اختر البلد", 1), makeField(-8, "governorate", "المحافظة", "select", "اختر المحافظة", 1), makeField(-9, "area", "المنطقة", "select", "اختر المنطقة", 1), makeField(-10, "age", "العمر", "number", "اكتب العمر"), makeField(-11, "nationality", "الجنسية", "select", "اختر الجنسية"), makeField(-12, "job", "الوظيفة", "select", "اختر الوظيفة"), makeField(-13, "interestStatus", "اهتمام العميل", "select", "اختر درجة الاهتمام", 1, "half", '["مهتم جدا","مهتم","متردد","مش مهتم"]'), makeField(-14, "offer", "العرض", "select", "اختر العرض"), makeField(-15, "notes", "نوت المكالمة", "textarea", "اكتب ملاحظات المكالمة", 0, "full")];
  const offerFieldIndex = fields.findIndex((field) => field.fieldKey === "offer");
  if (offerFieldIndex >= 0) fields.splice(offerFieldIndex, 1, makeField(-14, "segment", "السيجمنت", "select", "اختر السيجمنت"));
  const isEgypt = values.country === "مصر";
  if (!isEgypt) {
    for (let index = fields.length - 1; index >= 0; index -= 1) {
      if (fields[index].fieldKey === "governorate" || fields[index].fieldKey === "area") fields.splice(index, 1);
    }
  }
  useEffect(() => {
    if (values.country !== "مصر" && (values.governorate || values.area)) {
      setValues((current) => {
        const next = { ...current };
        delete next.governorate;
        delete next.area;
        return next;
      });
    }
  }, [values.country, values.governorate, values.area]);
  async function submit(e: FormEvent) {
    e.preventDefault();
    setBusy(true);
    setError("");
    try {
      const standard = new Set(["phone", "direction", "result", "assignedEmployeeId", "branchId", "callAt", "notes"]);
      const customData = Object.fromEntries(Object.entries(values).filter(([key]) => !standard.has(key)));
      await onSubmit({ ...values, customData });
    } catch (err) {
      setError(err instanceof Error ? err.message : "تعذر تسجيل المكالمة");
      setBusy(false);
    }
  }
  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <form className="dialog sales-dialog compact-sales" onSubmit={submit}>
        <div className="dialog-head">
          <div>
            <span className="dialog-icon">☎</span>
            <div>
              <h2>تسجيل مكالمة جديدة</h2>
              <p>لو الرقم مسجل سيتم ربط المكالمة بالعميل تلقائيًا.</p>
            </div>
          </div>
          <button type="button" onClick={onClose}>
            ×
          </button>
        </div>
        {error && <p className="form-error">{error}</p>}
        <div className="dynamic-grid dialog-fields">
          {fields.map((field) => (
            <DynamicField
              key={field.id}
              field={field}
              value={values[field.fieldKey]}
              setValue={(value) =>
                setValues((current) => ({
                  ...current,
                  [field.fieldKey]: value,
                }))
              }
              data={data}
              values={values}
            />
          ))}
        </div>
        <div className="dialog-foot">
          <button className="secondary" type="button" onClick={onClose}>
            إلغاء
          </button>
          <button className="primary" disabled={busy}>
            {busy ? "جارٍ التسجيل..." : "حفظ المكالمة"}
          </button>
        </div>
      </form>
    </div>
  );
}

