function TimeSlotDialog({ data, slot, onClose, onSubmit }: { data: Setup; slot: TimeSlot | null; onClose: () => void; onSubmit: (p: Record<string, unknown>) => Promise<void> }) {
  const base = slot
    ? {
        title: slot.title,
        startTime: slot.startTime,
        endTime: slot.endTime,
        isActive: slot.isActive ? "نشط" : "غير نشط",
      }
    : { isActive: "نشط" };
  let extras: Record<string, unknown> = {};
  try {
    extras = slot ? JSON.parse(slot.customData || "{}") : {};
  } catch {
    extras = {};
  }
  const [values, setValues] = useState<Record<string, unknown>>({
    ...extras,
    ...base,
  });
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  async function submit(event: FormEvent) {
    event.preventDefault();
    setBusy(true);
    setError("");
    try {
      await onSubmit(values);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "تعذر حفظ الفترة الزمنية");
      setBusy(false);
    }
  }
  return (
    <div className="overlay" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
      <form className="dialog time-dialog" onSubmit={submit}>
        <div className="dialog-head">
          <div>
            <span className="dialog-icon">◷</span>
            <div>
              <h2>{slot ? "تعديل الفترة" : "إضافة فترة زمنية"}</h2>
              <p>حدد الاسم ووقت البداية والنهاية.</p>
            </div>
          </div>
          <button type="button" onClick={onClose}>
            ×
          </button>
        </div>
        {error && <p className="form-error">{error}</p>}
        <div className="employee-form-note">
          <span>✓</span>
          <p>سيمنع النظام حفظ أي فترة نشطة تتداخل مع فترة أخرى.</p>
        </div>
        <div className="dynamic-grid dialog-fields">
          {data.timeSlotFields
            .filter((field) => field.visible)
            .map((field) => (
              <DynamicField
                key={field.id}
                field={field}
                value={values[field.fieldKey]}
                setValue={(value) =>
                  setValues((current) => ({
                    ...current,
                    [field.fieldKey]: value,
                  }))
                }
                data={data}
                values={values}
              />
            ))}
        </div>
        <div className="dialog-foot">
          <button className="secondary" type="button" onClick={onClose}>
            إلغاء
          </button>
          <button className="primary" disabled={busy}>
            {busy ? "جارٍ الحفظ..." : slot ? "حفظ التعديلات" : "إضافة الفترة"}
          </button>
        </div>
      </form>
    </div>
  );
}
function BranchDialog({ data, branch, onClose, onSubmit }: { data: Setup; branch: Branch | null; onClose: () => void; onSubmit: (p: Record<string, unknown>) => Promise<void> }) {
  const [values, setValues] = useState<Record<string, unknown>>(
    branch
      ? {
          name: branch.name,
          address: branch.address,
          primaryPhone: branch.primaryPhone,
          secondaryPhone: branch.secondaryPhone,
          email: branch.email,
          socialUrl: branch.socialUrl,
          isActive: branch.isActive ? "نشط" : "غير نشط",
        }
      : { isActive: "نشط" },
  );
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  async function submit(e: FormEvent) {
    e.preventDefault();
    setBusy(true);
    setError("");
    try {
      await onSubmit(values);
    } catch (err) {
      setError(err instanceof Error ? err.message : "تعذر حفظ الفرع");
      setBusy(false);
    }
  }
  return (
    <div className="overlay" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <form className="dialog employee-dialog" onSubmit={submit}>
        <div className="dialog-head">
          <div>
            <span className="dialog-icon">⌂</span>
            <div>
              <h2>{branch ? "تعديل بيانات الفرع" : "إضافة فرع جديد"}</h2>
              <p>مصدر موحد للفروع في كل نماذج النظام.</p>
            </div>
          </div>
          <button type="button" onClick={onClose}>
            ×
          </button>
        </div>
        {error && <p className="form-error">{error}</p>}
        <div className="employee-form-note">
          <span>↻</span>
          <p>النموذج ديناميكي، وتحديث الفرع ينعكس فورًا على الموظفين والـLeads والمكالمات المرتبطة.</p>
        </div>
        <div className="dynamic-grid dialog-fields">
          {data.branchFields
            .filter((field) => field.visible)
            .map((field) => (
              <DynamicField
                key={field.id}
                field={field}
                value={values[field.fieldKey]}
                setValue={(value) =>
                  setValues((current) => ({
                    ...current,
                    [field.fieldKey]: value,
                  }))
                }
                data={data}
                values={values}
              />
            ))}
        </div>
        <div className="dialog-foot">
          <button className="secondary" type="button" onClick={onClose}>
            إلغاء
          </button>
          <button className="primary" disabled={busy}>
            {busy ? "جارٍ الحفظ..." : branch ? "حفظ التعديلات" : "إضافة الفرع"}
          </button>
        </div>
      </form>
    </div>
  );
}
function JobDialog({ departments, jobs, job, onClose, onSubmit }: { departments: Department[]; jobs: JobTitle[]; job: JobTitle | null; onClose: () => void; onSubmit: (p: Record<string, unknown>) => Promise<void> }) {
  return (
    <BaseDialog
      title={job ? "تعديل الدور الوظيفي" : "إضافة دور وظيفي"}
      subtitle="اختر القسم والدور الإداري الذي ترفع إليه هذه الوظيفة تقاريرها."
      icon="◆"
      onClose={onClose}
      submitText={job ? "حفظ التعديلات" : "إضافة الوظيفة"}
      onSubmit={async (e) => {
        e.preventDefault();
        const f = new FormData(e.currentTarget);
        await onSubmit({
          name: f.get("name"),
          departmentId: f.get("departmentId"),
          reportsToId: f.get("reportsToId"),
        });
      }}
    >
      <label className="full">
        <span>اسم الوظيفة *</span>
        <input name="name" required placeholder="مثال: مسؤول مبيعات" defaultValue={job?.name || ""} />
      </label>
      <label className="full">
        <span>القسم *</span>
        <select name="departmentId" required defaultValue={job?.departmentId || ""}>
          <option value="">اختر القسم</option>
          {departments.map((d) => (
            <option key={d.id} value={d.id}>
              {d.name}
            </option>
          ))}
        </select>
      </label>
      <label className="full">
        <span>يرفع تقاريره إلى</span>
        <select name="reportsToId" defaultValue={job?.reportsToId || ""}>
          <option value="">بدون مدير مباشر</option>
          {jobs
            .filter((candidate) => candidate.id !== job?.id)
            .map((candidate) => (
              <option key={candidate.id} value={candidate.id}>
                {candidate.name} — {candidate.department}
              </option>
            ))}
        </select>
      </label>
    </BaseDialog>
  );
}
function FieldDialog({ onClose, onSubmit }: { onClose: () => void; onSubmit: (p: Record<string, unknown>) => Promise<void> }) {
  return (
    <BaseDialog
      title="حقل جديد"
      subtitle="سيظهر داخل نموذج الإدخال المحدد"
      icon="▤"
      onClose={onClose}
      submitText="إضافة الحقل"
      onSubmit={async (e) => {
        e.preventDefault();
        const f = new FormData(e.currentTarget);
        await onSubmit({
          formKey: f.get("formKey"),
          label: f.get("label"),
          type: f.get("type"),
          placeholder: f.get("placeholder"),
          width: f.get("width"),
          required: f.get("required") === "on",
        });
      }}
    >
      <label className="full">
        <span>النموذج *</span>
        <select name="formKey" required>
          <option value="employee">الموظف</option>
          <option value="branch">الفرع</option>
          <option value="classroom">القاعة</option>
          <option value="track">الـTrack</option>
          <option value="time_slot">نظام الوقت</option>
          <option value="lead">Lead جديدة</option>
          <option value="call">المكالمة</option>
          <option value="lead_details">استكمال بيانات العميل</option>
          <option value="followup">المتابعة</option>
        </select>
      </label>
      <label className="full">
        <span>اسم الحقل *</span>
        <input name="label" required />
      </label>
      <label>
        <span>النوع</span>
        <select name="type">
          <option value="text">نص</option>
          <option value="number">رقم</option>
          <option value="date">تاريخ</option>
          <option value="time">وقت</option>
          <option value="textarea">نص طويل</option>
        </select>
      </label>
      <label>
        <span>العرض</span>
        <select name="width">
          <option value="half">نصف صف</option>
          <option value="full">صف كامل</option>
        </select>
      </label>
      <label className="full">
        <span>النص الإرشادي</span>
        <input name="placeholder" />
      </label>
      <label className="inline-check full">
        <input type="checkbox" name="required" /> حقل إلزامي
      </label>
    </BaseDialog>
  );
}
